<?php $adminTitle='Inquiries'; require __DIR__.'/_header.php'; $rows=[]; $f=app_path('data/inquiries.csv'); if(is_file($f) && ($h=fopen($f,'r'))){ $head=fgetcsv($h); while(($r=fgetcsv($h))!==false) if($head && count($head)===count($r)) $rows[]=array_combine($head,$r); fclose($h); $rows=array_reverse($rows); } ?>
<div class="admin-title"><div><span>CUSTOMER LEADS</span><h1>Inquiries</h1><p>Contact and catering requests submitted through the website.</p></div></div>
<div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Name</th><th>Contact</th><th>Details</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5">No inquiries yet.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td><?=e($r['created_at']??'')?></td><td><span class="tag"><?=e($r['type']??'')?></span></td><td><strong><?=e($r['name']??'')?></strong></td><td><?=e($r['email']??'')?><br><?=e($r['phone']??'')?></td><td><?php if(!empty($r['date'])):?><b>Event:</b> <?=e($r['date'])?> · <?=e($r['guests']??'')?> guests<br><?php endif;?><?=nl2br(e($r['message']??''))?></td></tr><?php endforeach;?></tbody></table></div>
<?php require __DIR__.'/_footer.php'; ?>
